/**
 * Unicode predicates that CPython's `int(str)` conversion depends on.
 *
 * `int()` on a str runs the text through two stages:
 *
 *   1. _PyUnicode_TransformDecimalAndSpaceToASCII() — every Unicode decimal
 *      digit becomes its ASCII counterpart, every non-ASCII whitespace code
 *      point becomes a plain space, and every other non-ASCII code point
 *      becomes '?' so that it is guaranteed to fail later.
 *   2. PyLong_FromString() — parses the resulting ASCII text, skipping only
 *      the ASCII whitespace accepted by Py_ISSPACE().
 *
 * The two stages use *different* whitespace sets, which is why '\x1c5' raises
 * ValueError while ' 5' evaluates to 5: U+001C is ASCII, so stage 1 leaves
 * it alone, and stage 2's Py_ISSPACE() does not accept it.
 */

const DECIMAL_DIGIT = /^\p{Nd}$/u;

/** Py_ISSPACE(): the only characters PyLong_FromString() skips. */
const ASCII_SPACE = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);

/**
 * Py_UNICODE_ISSPACE() restricted to code points above ASCII — the set stage 1
 * folds down to U+0020.
 */
const NON_ASCII_SPACE = new Set([
  0x0085, 0x00a0, 0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
]);

/** True for the ASCII whitespace that PyLong_FromString() skips. */
export function isAsciiSpace(codePoint) {
  return ASCII_SPACE.has(codePoint);
}

/** True for the non-ASCII whitespace that stage 1 folds to a plain space. */
export function isNonAsciiSpace(codePoint) {
  return NON_ASCII_SPACE.has(codePoint);
}

/**
 * Lazily built map of every Unicode decimal-digit code point to its value.
 *
 * Rather than carry a hand-maintained table, the map is derived from ICU data
 * that the runtime already ships: formatting 0-9 in each CLDR numbering system
 * yields exactly the code points in category Nd. On current Node builds this
 * reproduces all 680 Nd code points, and the boundary scan below covers any
 * digit a future Unicode revision adds ahead of CLDR.
 */
let digitValues = null;

function buildDigitValues() {
  const map = new Map();
  let systems;
  try {
    systems = Intl.supportedValuesOf('numberingSystem');
  } catch {
    systems = [];
  }
  for (const system of systems) {
    let format;
    try {
      format = new Intl.NumberFormat('en', { numberingSystem: system });
    } catch {
      continue;
    }
    for (let value = 0; value <= 9; value += 1) {
      const rendered = [...format.format(value)];
      // Algorithmic systems (roman numerals, tallies) render multiple chars.
      if (rendered.length !== 1 || !DECIMAL_DIGIT.test(rendered[0])) continue;
      const codePoint = rendered[0].codePointAt(0);
      if (!map.has(codePoint)) map.set(codePoint, value);
    }
  }
  return map;
}

/**
 * Fallback for an Nd code point ICU did not describe. Decimal digits are always
 * laid out as ten consecutive code points, so walking back to the first one
 * that is not preceded by another digit recovers the value.
 */
function scanDigitValue(codePoint) {
  for (let offset = 0; offset <= 9; offset += 1) {
    const zero = codePoint - offset;
    if (zero < 0 || !DECIMAL_DIGIT.test(String.fromCodePoint(zero))) break;
    const before = zero - 1;
    if (before < 0 || !DECIMAL_DIGIT.test(String.fromCodePoint(before))) return offset;
  }
  return -1;
}

/**
 * Py_UNICODE_TODECIMAL(): the value of a Unicode decimal digit, or -1 when the
 * code point is not one. Numeric characters outside category Nd — '½', '²',
 * 'Ⅷ', '①' — are deliberately rejected, matching CPython.
 */
export function decimalDigitValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30;
  if (codePoint < 0x80) return -1;
  if (!DECIMAL_DIGIT.test(String.fromCodePoint(codePoint))) return -1;
  if (digitValues === null) digitValues = buildDigitValues();
  const known = digitValues.get(codePoint);
  return known === undefined ? scanDigitValue(codePoint) : known;
}

const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/**
 * str.isprintable() for a single code point: everything in the C* and Z*
 * categories is unprintable, except the plain space.
 */
export function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/** Iterates a string by code point, the way Python iterates a str. */
export function codePointsOf(text) {
  return [...text].map((character) => character.codePointAt(0));
}

