/**
 * Python's repr()/print() formatting for the values this program emits.
 */

import { isPrintable } from './pyunicode.mjs';

const SHORT_ESCAPES = new Map([
  [0x5c, '\\\\'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
  [0x09, '\\t'],
]);

function escapeCodePoint(codePoint) {
  if (codePoint <= 0xff) return `\\x${codePoint.toString(16).padStart(2, '0')}`;
  if (codePoint <= 0xffff) return `\\u${codePoint.toString(16).padStart(4, '0')}`;
  return `\\U${codePoint.toString(16).padStart(8, '0')}`;
}

/**
 * repr() of a str: single quotes unless the text contains a single quote and no
 * double quote, in which case Python switches the outer quotes rather than
 * escaping.
 */
export function reprString(text) {
  const characters = [...text];
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let out = quote;
  for (const character of characters) {
    const codePoint = character.codePointAt(0);
    const short = SHORT_ESCAPES.get(codePoint);
    if (short !== undefined) {
      out += short;
    } else if (character === quote) {
      out += `\\${character}`;
    } else if (!isPrintable(codePoint)) {
      out += escapeCodePoint(codePoint);
    } else {
      out += character;
    }
  }
  return out + quote;
}

/** repr() of an int. BigInt keeps Python's unbounded precision. */
export function reprInt(value) {
  return value.toString();
}

/** repr() of a list of ints: "[3, 3, 0, 20, 2]". */
export function reprIntList(values) {
  return `[${values.map(reprInt).join(', ')}]`;
}

/** print(): writes the text plus a trailing newline to stdout. */
export function pyPrint(text) {
  process.stdout.write(`${text}\n`);
}

