/**
 * The slice of Python's error reporting this program can reach: a ValueError
 * escaping main(), and the SystemExit that argparse raises.
 */

/** Python's ValueError. */
export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
    this.pythonType = 'ValueError';
  }
}

/** Python's SystemExit, as raised by parser.exit()/parser.error(). */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * The interpreter frames between module scope and the failing statement. The
 * frozen binary reports the original test9.py source lines, so they are
 * reproduced verbatim.
 */
const TRACEBACK_FRAMES = [
  { line: 18, scope: '<module>', source: 'main()' },
  {
    line: 10,
    scope: 'main',
    source: "data = list(map(int, args.b.split(',')))",
    // The ^ run PEP 657 draws under the sub-expression that raised.
    marker: '^'.repeat("list(map(int, args.b.split(',')))".length),
    markerOffset: 'data = '.length,
  },
];

const FRAME_INDENT = '  ';
const SOURCE_INDENT = '    ';

/** Renders the traceback CPython prints for an uncaught exception. */
export function formatTraceback(error, scriptName) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of TRACEBACK_FRAMES) {
    lines.push(`${FRAME_INDENT}File "${scriptName}", line ${frame.line}, in ${frame.scope}`);
    lines.push(`${SOURCE_INDENT}${frame.source}`);
    if (frame.marker) {
      lines.push(`${SOURCE_INDENT}${' '.repeat(frame.markerOffset)}${frame.marker}`);
    }
  }
  lines.push(`${error.pythonType ?? error.name}: ${error.message}`);
  return `${lines.join('\n')}\n`;
}

/**
 * Runs a Python-style main(), mapping escaping exceptions onto the same stderr
 * text and exit status the frozen executable produces.
 *
 * @param {() => void} main
 * @param {{scriptName: string, moduleName: string}} options
 */
export function runPythonMain(main, { scriptName, moduleName }) {
  try {
    main();
  } catch (error) {
    if (error instanceof SystemExit) {
      process.exitCode = error.code;
      return;
    }
    if (error instanceof ValueError) {
      process.stderr.write(formatTraceback(error, scriptName));
      // PyInstaller's bootloader appends this line, tagged with its own pid.
      process.stderr.write(
        `[PYI-${process.pid}:ERROR] Failed to execute script '${moduleName}' due to unhandled exception!\n`,
      );
      process.exitCode = 1;
      return;
    }
    throw error;
  }
}

