/**
 * int(str) with CPython's exact acceptance rules, returning a BigInt so that
 * Python's unbounded integer precision survives the port.
 */

import { decimalDigitValue, isAsciiSpace, isNonAsciiSpace } from './pyunicode.mjs';
import { ValueError } from './pyerrors.mjs';
import { reprString } from './pyrepr.mjs';

const INVALID = '?';

/**
 * Stage 1 — _PyUnicode_TransformDecimalAndSpaceToASCII(). Decimal digits fold
 * to ASCII digits, non-ASCII whitespace folds to a space, and any other
 * non-ASCII code point becomes a character stage 2 is certain to reject.
 */
function transformToAscii(text) {
  let out = '';
  for (const character of text) {
    const codePoint = character.codePointAt(0);
    const digit = decimalDigitValue(codePoint);
    if (digit >= 0) {
      out += String(digit);
    } else if (codePoint < 0x80) {
      out += character;
    } else if (isNonAsciiSpace(codePoint)) {
      out += ' ';
    } else {
      out += INVALID;
    }
  }
  return out;
}

/**
 * Stage 2 — PyLong_FromString() for base 10. Returns null on any malformed
 * input so the caller can raise with the original text in the message.
 */
function parseAsciiDecimal(text) {
  const length = text.length;
  let index = 0;

  while (index < length && isAsciiSpace(text.charCodeAt(index))) index += 1;

  let negative = false;
  if (index < length && (text[index] === '+' || text[index] === '-')) {
    negative = text[index] === '-';
    index += 1;
  }

  // At least one digit is required, and underscores may only sit between two
  // digits: '1_0' is 10, while '_1', '1_' and '1__0' are all errors.
  let digits = '';
  let expectDigit = true;
  while (index < length) {
    const character = text[index];
    if (character >= '0' && character <= '9') {
      digits += character;
      expectDigit = false;
      index += 1;
    } else if (character === '_' && !expectDigit) {
      expectDigit = true;
      index += 1;
    } else {
      break;
    }
  }
  if (digits.length === 0 || expectDigit) return null;

  while (index < length && isAsciiSpace(text.charCodeAt(index))) index += 1;
  if (index !== length) return null;

