  while (index < length && isAsciiSpace(text.charCodeAt(index))) index += 1;

  let negative = false;
  if (index < length && (text[index] === '+' || text[index] === '-')) {
    negative = text[index] === '-';
    index += 1;
  }

  // At least one digit is required, and underscores may only sit between two
  // digits: '1_0' is 10, while '_1', '1_' and '1__0' are all errors.
  let digits = '';
  let expectDigit = true;
  while (index < length) {
    const character = text[index];
    if (character >= '0' && character <= '9') {
      digits += character;
      expectDigit = false;
      index += 1;
