/**
 * The two bech32 primitives this program uses, reconstructed from the observed
 * behaviour of the Python `bech32` module.
 *
 * Both operate on BigInt values. The Python originals accept arbitrary ints —
 * negative values and values far beyond 64 bits both flow through the checksum
 * arithmetic and can appear in the result — so plain JS numbers would silently
 * lose precision. BigInt reproduces Python's two's-complement bitwise
 * semantics and floor shifts exactly.
 */

/** The BCH generator constants behind the bech32 checksum. */
const GENERATOR = [0x3b6a57b2n, 0x26508e6dn, 0x1ea119fan, 0x3d4233ddn, 0x2a1462b3n];

const CHECKSUM_MASK = 0x1ffffffn;

/**
 * bech32_hrp_expand(hrp): the high bits of every character, a zero separator,
 * then the low five bits of every character.
 *
 * Iteration is by code point, matching Python's `for x in hrp` — so an astral
 * character such as '😀' contributes its full U+1F600 value, not a surrogate.
 *
 * @param {string} hrp
 * @returns {bigint[]}
 */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const character of hrp) {
    const codePoint = BigInt(character.codePointAt(0));
    high.push(codePoint >> 5n);
    low.push(codePoint & 31n);
  }
  return [...high, 0n, ...low];
}

/**
 * bech32_polymod(values): the running BCH checksum over the value sequence.
 *
 * @param {bigint[]} values
 * @returns {bigint}
 */
export function bech32Polymod(values) {
  let checksum = 1n;
  for (const value of values) {
    const top = checksum >> 25n;
    checksum = ((checksum & CHECKSUM_MASK) << 5n) ^ value;
    for (let bit = 0; bit < 5; bit += 1) {
      if ((top >> BigInt(bit)) & 1n) checksum ^= GENERATOR[bit];
    }
  }
  return checksum;
}

