/**
 * argparse's HelpFormatter, reduced to the layout this parser needs.
 */

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** The "-h, --help" / "--a A" text argparse puts in the left column. */
function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((option) => `${option} ${action.metavar}`).join(', ');
}

/** The bracketed/plain form each action takes in the usage line. */
function formatUsagePart(action) {
  const option = action.optionStrings[0];
  const body = action.nargs === 0 ? option : `${option} ${action.metavar}`;
  return action.required ? body : `[${body}]`;
}

export function formatUsage(prog, actions) {
  const parts = actions.map(formatUsagePart);
  return `usage: ${[prog, ...parts].join(' ')}\n`;
}

export function formatHelp(prog, actions) {
  // argparse measures the left column including the indent, then caps where
  // help text may start.
  const widest = actions.reduce(
    (max, action) => Math.max(max, formatInvocation(action).length + INDENT),
    0,
  );
  const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);

  const lines = [formatUsage(prog, actions), '\n', 'options:\n'];
  for (const action of actions) {
    const invocation = formatInvocation(action);
    if (!action.help) {
      lines.push(`${' '.repeat(INDENT)}${invocation}\n`);
      continue;
    }
    const label = `${' '.repeat(INDENT)}${invocation}`;
    if (label.length < helpPosition) {
      lines.push(`${label.padEnd(helpPosition)}${action.help}\n`);
    } else {
      // Too wide for the column: argparse drops the help onto the next line.
      lines.push(`${label}\n${' '.repeat(helpPosition)}${action.help}\n`);
    }
  }
  return lines.join('');
}

