/**
 * The subset of Python's argparse.ArgumentParser needed to mirror test9.py:
 * required long options that store a single string value, the implicit
 * -h/--help action, long-option abbreviation, the '--' separator, and
 * argparse's exact error messages and exit statuses.
 */

import { SystemExit } from './pyerrors.mjs';
import { formatHelp, formatUsage } from './helpformatter.mjs';

/**
 * argparse's _negative_number_matcher. When no option string itself looks like
 * a negative number, tokens matching this are values rather than options —
 * which is why `--b -3` works but `--b -3,+4` does not.
 */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();
    this.hasNegativeNumberOptionals = false;
    this.addArgument(['-h', '--help'], {
      nargs: 0,
      isHelp: true,
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, { nargs = 1, required = false, isHelp = false, help = '' } = {}) {
    const dest = optionStrings
      .find((option) => option.startsWith('--'))
      .replace(/^--/, '')
      .replace(/-/g, '_');
    const action = {
      optionStrings,
      dest,
      nargs,
      required,
      isHelp,
      help,
      metavar: dest.toUpperCase(),
    };
    this.actions.push(action);
    for (const option of optionStrings) {
      this.optionStringActions.set(option, action);
      if (NEGATIVE_NUMBER.test(option)) this.hasNegativeNumberOptionals = true;
    }
    return action;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  /** parser.exit(): flushes nothing and raises SystemExit. */
  exit(status = 0) {
    throw new SystemExit(status);
  }

  /** parser.error(): usage plus message on stderr, then exit status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    this.exit(2);
  }

  /**
   * Whether a token can be consumed as an option's value. Mirrors the negative
   * conditions in argparse's _parse_optional().
   */
  looksLikeValue(token, afterSeparator) {
    if (afterSeparator) return true;
    if (token === '') return true;
    if (!token.startsWith('-')) return true;
    if (token.length === 1) return true; // a bare '-' is positional
    if (token === '--') return false; // the separator is never a value
    if (NEGATIVE_NUMBER.test(token) && !this.hasNegativeNumberOptionals) return true;
    if (token.includes(' ')) return true;
    return false;
  }

  /** argparse's _get_option_tuples(): abbreviation and joined-argument matching. */
  getOptionTuples(token) {
    const matches = [];
    if (token.startsWith('--')) {
      let prefix = token;
      let explicitArg = null;
      const equals = token.indexOf('=');
      if (equals !== -1) {
        prefix = token.slice(0, equals);
        explicitArg = token.slice(equals + 1);
      }
      for (const [option, action] of this.optionStringActions) {
        if (option.startsWith(prefix)) matches.push({ action, option, explicitArg });
      }
      return matches;
    }
    const shortPrefix = token.slice(0, 2);
    const shortExplicit = token.slice(2);
    for (const [option, action] of this.optionStringActions) {
      if (option === shortPrefix) {
        matches.push({ action, option, explicitArg: shortExplicit === '' ? null : shortExplicit });
      } else if (option.startsWith(token)) {
        matches.push({ action, option, explicitArg: null });
      }
    }
    return matches;
  }

  /** argparse's _parse_optional(). A null action means "unrecognized". */
  parseOptional(token) {
    const exact = this.optionStringActions.get(token);
    if (exact) return { action: exact, option: token, explicitArg: null };

    const equals = token.indexOf('=');
    if (equals !== -1) {
      const option = token.slice(0, equals);
      const action = this.optionStringActions.get(option);
      if (action) return { action, option, explicitArg: token.slice(equals + 1) };
    }

    const matches = this.getOptionTuples(token);
    if (matches.length > 1) {
      const options = matches.map((match) => match.option).join(', ');
      this.error(`ambiguous option: ${token} could match ${options}`);
    }
    if (matches.length === 1) return matches[0];
    return { action: null, option: token, explicitArg: null };
  }

  /**
   * parse_known_args(): fills the namespace and collects anything unrecognized.
   * Missing required options are reported here, which is why they take
   * precedence over "unrecognized arguments".
   */
  parseKnownArgs(argv) {
    const namespace = {};
    for (const action of this.actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }

    const seen = new Set();
    const extras = [];
    let afterSeparator = false;
    let index = 0;

    while (index < argv.length) {
      const token = argv[index];

      if (afterSeparator) {
        extras.push(token);
        index += 1;
        continue;
      }
      if (token === '--') {
        afterSeparator = true;
        index += 1;
        continue;
      }
      if (this.looksLikeValue(token, false)) {
        extras.push(token);
        index += 1;
        continue;
      }

      const { action, explicitArg } = this.parseOptional(token);
      if (!action) {
        extras.push(token);
        index += 1;
        continue;
      }

      // The help action fires the moment it is seen, before required-argument
      // and unrecognized-argument checks run.
      if (action.isHelp) {
        this.printHelp();
        this.exit(0);
      }

      const name = action.optionStrings.join('/');
      if (explicitArg !== null) {
        namespace[action.dest] = explicitArg;
        index += 1;
