/**
 * Python's linecache, as the traceback machinery uses it.
 *
 * A frozen PyInstaller build carries no source, so CPython falls back to
 * resolving the code object's filename — the bare relative name "test9.py" —
 * against the current working directory. That is why the traceback grows source
 * and caret lines when the program runs from a directory containing test9.py
 * and loses them everywhere else.
 */

import { readFileSync } from 'node:fs';

/**
 * getline(): the raw 1-indexed line, newline included, or null when the file or
 * line cannot be read. Never throws.
 *
 * @param {string} filename
 * @param {number} lineNumber
 * @returns {string | null}
 */
export function getLine(filename, lineNumber) {
  let contents;
  try {
    contents = readFileSync(filename, 'utf8');
  } catch {
    return null;
  }
  // splitlines(keepends=True): keep the terminator, since the traceback's caret
  // clamping measures the line's full length.
  const lines = contents.match(/[^\n]*\n|[^\n]+/g);
  if (!lines || lineNumber < 1 || lineNumber > lines.length) return null;
  return lines[lineNumber - 1];
}

/** The UTF-8 length of a single code point, without touching a byte buffer. */
function utf8Length(codePoint) {
  if (codePoint < 0x80) return 1;
  if (codePoint < 0x800) return 2;
  if (codePoint < 0x10000) return 3;
  return 4;
}

/**
 * traceback._byte_offset_to_character_offset(): converts a code object's byte
 * column offset into a character index, clamping to the end of the line when the
 * offset runs past it.
 *
 * @param {string} line
 * @param {number} byteOffset
 * @returns {number}
 */
export function byteOffsetToCharOffset(line, byteOffset) {
  let bytesSeen = 0;
  let characters = 0;
  for (const character of line) {
    const width = utf8Length(character.codePointAt(0));
    if (bytesSeen + width > byteOffset) return characters;
    bytesSeen += width;
    characters += 1;
  }
  return characters;
}

