/**
 * The slice of Python's error reporting this program can reach: a ValueError
 * escaping main(), and the SystemExit that argparse raises.
 */

import { byteOffsetToCharOffset, getLine } from './linecache.mjs';

/** Python's ValueError. */
export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
    this.pythonType = 'ValueError';
  }
}

/** Python's SystemExit, as raised by parser.exit()/parser.error(). */
export class SystemExit extends Error {
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * The frames between module scope and the failing statement, with the column
 * offsets the compiler recorded for the expression that raises in each. The
 * offsets are byte offsets into the original, unstripped source line, which is
 * what PEP 657 stores and what the caret line is derived from.
 */
const TRACEBACK_FRAMES = [
  // `main()` inside `    main()`
  { lineNumber: 18, scope: '<module>', colno: 4, endColno: 10 },
  // `list(map(int, args.b.split(',')))` inside `    data = list(...)`
  { lineNumber: 10, scope: 'main', colno: 11, endColno: 44 },
];

const FRAME_INDENT = '  ';
const SOURCE_INDENT = '    ';

/**
 * Renders one frame's source and caret lines, mirroring
 * StackSummary.format_frame_summary(). Returns an empty list when linecache
 * cannot supply the line, which is how the frozen build behaves outside the
 * source directory.
 */
function formatFrameSource(rawLine, frame) {
  if (rawLine === null) return [];

  const stripped = rawLine.trim();
  if (stripped === '') return [];
  const lines = [`${SOURCE_INDENT}${stripped}`];

  // Leading whitespace that display dropped; caret offsets shift by the same
  // amount so they stay aligned with the stripped text.
  const strippedCharacters = rawLine.length - rawLine.replace(/^\s+/, '').length;
  const left = byteOffsetToCharOffset(rawLine, frame.colno) - strippedCharacters;
  const right = byteOffsetToCharOffset(rawLine, frame.endColno) - strippedCharacters;

  // When the anchor spans the whole statement there is nothing to point out, so
  // CPython omits the caret line entirely.
  if (left <= 0 && right >= stripped.length) return lines;
  if (right <= left) return lines;

  const padding = Math.max(left, 0);
  lines.push(`${SOURCE_INDENT}${' '.repeat(padding)}${'^'.repeat(right - padding)}`);
  return lines;
}

/** Renders the traceback CPython prints for an uncaught exception. */
export function formatTraceback(error, scriptName) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of TRACEBACK_FRAMES) {
    lines.push(
      `${FRAME_INDENT}File "${scriptName}", line ${frame.lineNumber}, in ${frame.scope}`,
    );
    lines.push(...formatFrameSource(getLine(scriptName, frame.lineNumber), frame));
  }
  lines.push(`${error.pythonType ?? error.name}: ${error.message}`);
  return `${lines.join('\n')}\n`;
}

/**
 * Runs a Python-style main(), mapping escaping exceptions onto the same stderr
 * text and exit status the frozen executable produces.
 *
 * @param {() => void} main
 * @param {{scriptName: string, moduleName: string}} options
 */
export function runPythonMain(main, { scriptName, moduleName }) {
  try {
    main();
  } catch (error) {
    if (error instanceof SystemExit) {
      process.exitCode = error.code;
      return;
    }
    if (error instanceof ValueError) {
      process.stderr.write(formatTraceback(error, scriptName));
      // PyInstaller's bootloader appends this line, tagged with its own pid.
      process.stderr.write(
        `[PYI-${process.pid}:ERROR] Failed to execute script '${moduleName}' due to unhandled exception!\n`,
      );
      process.exitCode = 1;
      return;
    }
    throw error;
  }
}

